import{_ as a,o,c as t,a2 as r}from"./chunks/framework.DbKnw1Aw.js";const f=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1794449059000}'),d={name:"guide/faq.md"};function c(i,e,l,n,s,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="客户端更新订阅失败" tabindex="-1">客户端更新订阅失败 <a class="header-anchor" href="#客户端更新订阅失败" aria-label="Permalink to &quot;客户端更新订阅失败&quot;">​</a></h2><p>先把订阅链接（或短链）直接粘贴到浏览器打开，看 Worker 返回了什么：</p><table tabindex="0"><thead><tr><th>返回</th><th>原因</th></tr></thead><tbody><tr><td><code>Missing config parameter</code></td><td>链接里没有节点，或节点内容为空</td></tr><tr><td><code>Internal Server Error</code></td><td>生成过程中出错，常见于节点链接格式异常</td></tr><tr><td><code>Short URL not found</code></td><td>旧版 <code>/s/</code> 短链不存在</td></tr><tr><td>跳转到 <code>…/clashnull</code>、<code>…/singboxnull</code> 一类地址</td><td><code>/c/</code> <code>/b/</code> <code>/x/</code> 短链的路径不存在。这是从原项目沿用的行为，此时不会返回 404</td></tr></tbody></table><p>另外检查：</p><ul><li>机场是否限制了 Cloudflare 的出口 IP。如果 Worker 拉取订阅超时，可以直接粘贴节点链接，而不是订阅地址。</li></ul><h2 id="workers-dev-打不开" tabindex="-1"><code>*.workers.dev</code> 打不开 <a class="header-anchor" href="#workers-dev-打不开" aria-label="Permalink to &quot;`*.workers.dev` 打不开&quot;">​</a></h2><p>部分网络无法访问 <code>workers.dev</code> 域名，在 Cloudflare 控制台为 Worker 绑定自己的域名即可。</p><h2 id="为什么有些分组默认直连" tabindex="-1">为什么有些分组默认直连 <a class="header-anchor" href="#为什么有些分组默认直连" aria-label="Permalink to &quot;为什么有些分组默认直连&quot;">​</a></h2><p>哔哩哔哩、私有网络、国内服务、苹果、微软五个分组默认选中 <code>DIRECT</code>：局域网设备、国内网站（含哔哩哔哩），以及苹果、微软在国内有节点的服务，直连通常更快也更稳定。组内仍然保留节点选项，可以在客户端里随时切换。</p><p>广告拦截默认选中 <code>REJECT</code>。它使用的 <code>category-ads-all</code> 名单也包含 Sentry、Segment 等统计服务的完整域名，如果你需要访问其中某个服务，添加一条置顶的快捷规则（直连 + 域名后缀，例如 <code>sentry.io</code>）即可放行。</p><h2 id="改了规则后要更换订阅地址吗" tabindex="-1">改了规则后要更换订阅地址吗 <a class="header-anchor" href="#改了规则后要更换订阅地址吗" aria-label="Permalink to &quot;改了规则后要更换订阅地址吗&quot;">​</a></h2><p>不需要。用之前的短链路径再生成一次短链，内容会被覆盖，客户端下次更新订阅即可拿到新配置。见<a href="./links#用同一路径更新">订阅链接与短链</a>。</p><h2 id="客户端里手动选的节点-重启后变回去了" tabindex="-1">客户端里手动选的节点，重启后变回去了 <a class="header-anchor" href="#客户端里手动选的节点-重启后变回去了" aria-label="Permalink to &quot;客户端里手动选的节点，重启后变回去了&quot;">​</a></h2><p>Clash 系客户端需要开启 <code>profile.store-selected</code>（在客户端设置中通常叫&quot;记住选择&quot;之类的选项）。sing-box 的配置已开启 <code>cache_file</code>，会记住选择。见<a href="./groups#手动选择会被记住吗">策略组</a>。</p><h2 id="geo-site-名称怎么查" tabindex="-1">Geo-Site 名称怎么查 <a class="header-anchor" href="#geo-site-名称怎么查" aria-label="Permalink to &quot;Geo-Site 名称怎么查&quot;">​</a></h2><p>可用的分类名就是 <a href="https://github.com/v2fly/domain-list-community/tree/master/data" target="_blank" rel="noreferrer">v2fly/domain-list-community</a> 中 <code>data/</code> 目录下的文件名。在高级规则里填写后，页面会在线检查名称是否存在；不存在的名称会标红，因为 sing-box 下载对应规则集失败会导致整份配置无法加载。</p><h2 id="为什么去掉了原项目的-底板配置" tabindex="-1">为什么去掉了原项目的&quot;底板配置&quot; <a class="header-anchor" href="#为什么去掉了原项目的-底板配置" aria-label="Permalink to &quot;为什么去掉了原项目的&quot;底板配置&quot;&quot;">​</a></h2><p>原项目（<a href="https://github.com/7Sageer/sublink-worker" target="_blank" rel="noreferrer">7Sageer/sublink-worker</a>，本项目由它派生，现已各自独立演进）允许保存一份自定义的 Clash / sing-box 模板（<code>POST /config</code> + <code>configId</code>），实际使用中问题较多：</p><ul><li><code>configId</code> 同时拼进所有订阅链接，但服务端不检查类型，保存 Clash 模板后 sing-box 链接会报 500，反之亦然；</li><li>模板缺少必需字段时同样报 500；</li><li>模板 30 天后过期，过期后订阅悄悄退回默认模板，客户端没有任何提示；</li><li>端口、TUN 等设置大多会被客户端自身的设置覆盖。</li></ul><p>旧链接里的 <code>configId</code> 参数现在会被忽略，链接照常可用。</p>',21)])])}const p=a(d,[["render",c]]);export{f as __pageData,p as default};
